SERVICES = [
('gebaeudereinigung','Gebäudereinigung','Sauberkeit, die bleibt.','service-0.webp','Unterhaltsreinigung, Glasreinigung und gezielte Sonderreinigung für gepflegte Arbeits- und Lebensräume.',[
('Regelmäßig gut gepflegt','Eine saubere Immobilie beginnt mit einem klaren Reinigungsplan. Wir stimmen Flächen, Materialien, Nutzung und Intervalle aufeinander ab. Büroarbeitsplätze, Sanitärbereiche, Treppenhäuser und Gemeinschaftsflächen erhalten genau die Pflege, die im Alltag benötigt wird. Die Ausführung lässt sich an Ihre Betriebszeiten anpassen.'),
('Vom Glas bis zum Polster','Unser Leistungsspektrum umfasst Unterhalts-, Grund-, Baufein-, Glas- und Treppenhausreinigung. Auch Polster- und Teppichreinigung gehören dazu. Bei hartnäckigen Rückständen prüfen wir zunächst Oberfläche und Material, damit Verfahren und Reinigungsmittel zusammenpassen.'),
('Nachvollziehbar abgestimmt','Vor Beginn halten wir fest, welche Arbeiten in welchem Rhythmus erfolgen. Sonderleistungen werden gesondert vereinbart. Unsere Objektbetreuung begleitet die Ausführung und nimmt Rückmeldungen auf – damit aus einem guten ersten Eindruck dauerhaft gepflegte Räume werden.')],['Unterhaltsreinigung','Grund- & Baufeinreinigung','Glas- & Treppenhausreinigung','Polster- & Teppichpflege']),
('wachschutz','Wachschutz','Sicherheit mit System.','service-3.webp','Objektbewachung, Revierkontrollen und Empfangsdienste gemeinsam mit der WSG innerhalb der FORM Gruppe.',[
('Ein Schutzkonzept für Ihr Objekt','Betriebsabläufe, Zugänge und Nutzungszeiten bestimmen, welche Sicherheitsleistungen sinnvoll sind. Gemeinsam mit der WSG entwickeln wir eine abgestimmte Betreuung für Gewerbeobjekte, Wohnanlagen und öffentliche Einrichtungen. Dauerhafte Präsenz und mobile Kontrollen können passend kombiniert werden.'),
('Kontrollieren, dokumentieren, reagieren','Zum Leistungsspektrum zählen Objekt-, Gebäude- und Werkschutz, Revierbewachung, Schließdienste sowie Empfangs- und Besucherservice. Kontrollpunkte, Meldewege und Zuständigkeiten werden vorab vereinbart. Auffälligkeiten werden dokumentiert und an die vorgesehenen Ansprechpartner weitergegeben.'),
('Stark im Verbund','Als Unternehmen der FORM Gruppe verbindet COMPAKT die regionale Betreuung mit den Sicherheitskompetenzen der WSG. Auch Alarm- und Videotechnik sowie die Anbindung an eine Notrufzentrale können in ein individuelles Konzept einbezogen werden. Wir klären mit Ihnen, welche Lösung zum tatsächlichen Bedarf passt.')],['Objekt- & Werkschutz','Revier- & Schließdienst','Empfangs- & Besucherservice','Alarm- & Videotechnik']),
('winterdienst','Winterdienst','Gut vorbereitet auf Frost.','service-5.webp','Schneeräumung und Streudienst für Gehwege, Zugänge, Zufahrten und betriebliche Außenflächen.',[
('Vor dem ersten Frost planen','Ein verlässlicher Winterdienst beginnt mit einer Bestandsaufnahme. Welche Wege werden täglich genutzt? Wo liegen Eingänge, Rampen oder empfindliche Beläge? Wir stimmen Räumflächen, Zugänglichkeit und die vereinbarten Leistungen mit Ihnen ab, bevor Schnee und Glätte den Alltag bestimmen.'),
('Räumen und streuen','Wir übernehmen die Schneeräumung und Glättebekämpfung auf den vereinbarten Flächen. Je nach Objekt kommen geeignete Geräte und Streumittel zum Einsatz. Zugänge und notwendige Verkehrswege werden bei der Planung berücksichtigt; örtliche Vorgaben fließen in die Abstimmung ein.'),
('Klare Zuständigkeiten im Winter','Für Wohnungsverwaltungen, Unternehmen und Eigentümer ist besonders wichtig, wer wann erreichbar ist. Deshalb besprechen wir Einsatzorganisation und Rückmeldungen gemeinsam. Änderungen an Flächen, Baustellen oder Zufahrten sollten frühzeitig mitgeteilt werden, damit der Winterdienst darauf reagieren kann.')],['Schneeräumung','Streudienst','Gehwege & Eingänge','Zufahrten & Außenflächen']),
('grafittientfernung','Graffiti-Entfernung','Eine Fassade. Ein guter Eindruck.','service-2.webp','Materialgerechte Entfernung unerwünschter Farbschmierereien auf Fassaden, Mauern und weiteren Oberflächen.',[
('Jede Oberfläche ist anders','Putz, Naturstein, Klinker, Metall und Glas reagieren unterschiedlich auf Reinigungsverfahren. Deshalb prüfen wir zunächst Untergrund, Zustand und Verschmutzung. Eine Probefläche hilft, das geeignete Verfahren zu bestimmen und die Wirkung vorab einzuschätzen.'),
('Gezielt und sorgfältig entfernen','Wir stimmen Reinigungsmittel und Technik auf die betreffende Fläche ab. Dabei geht es um ein möglichst sauberes Ergebnis bei sorgfältigem Umgang mit der Bausubstanz. Bereits vorhandene Schäden, offenporige Materialien oder ältere Farbschichten berücksichtigen wir bei der Planung.'),
('Künftige Reinigung mitdenken','Auf Wunsch beraten wir zu einer geeigneten Anti-Graffiti-Beschichtung. Ob ein Schutzsystem sinnvoll ist, hängt vom Untergrund, der Nutzung und der Belastung ab. Senden Sie uns Fotos und Angaben zum Material – so können wir das weitere Vorgehen vorbereiten.')],['Fassaden & Mauern','Stein, Putz, Glas & Metall','Materialprüfung','Anti-Graffiti-Schutz nach Beratung']),
('hausmeister','Hausmeisterdienst','Jemand, der sich kümmert.','service-4.webp','Regelmäßige Objektkontrollen, Pflege und die Koordination anstehender Arbeiten rund um Ihre Immobilie.',[
('Das Gebäude im Blick','Kleine Auffälligkeiten sollten nicht liegen bleiben. Bei regelmäßigen Begehungen kontrollieren wir vereinbarte Bereiche, nehmen Mängel auf und informieren die zuständigen Ansprechpartner. Beleuchtung, Türen, Gemeinschaftsflächen und Außenbereiche lassen sich in einen festen Kontrollplan aufnehmen.'),
('Praktische Hilfe im Alltag','Zu den Aufgaben gehören Gebäudepflege, Mülltonnenbereitstellung, vereinbarte Kleinreparaturen und die Betreuung gemeinschaftlich genutzter Flächen. Fachpflichtige Arbeiten koordinieren wir mit entsprechend qualifizierten Unternehmen. So bleiben Zuständigkeiten klar und Arbeiten nachvollziehbar.'),
('Eine Verbindung zwischen allen Beteiligten','Wir unterstützen Eigentümer und Hausverwaltungen bei der Abstimmung mit Mietern und Dienstleistern. Mängelmeldungen, Termine und erledigte Aufgaben werden nach Vereinbarung dokumentiert. Reinigung, Grünpflege und Winterdienst können ergänzend eingebunden werden.')],['Regelmäßige Objektkontrollen','Mängelaufnahme & Dokumentation','Müllmanagement','Dienstleisterkoordination']),
('gruenflaechenpflege','Grünflächenpflege','Draußen gut aufgehoben.','service-6.webp','Saisonale Pflege für Rasen, Hecken, Beete und Wege an Wohnanlagen und Gewerbeobjekten.',[
('Pflege passend zur Jahreszeit','Grünanlagen brauchen im Frühjahr andere Aufmerksamkeit als im Hochsommer oder Herbst. Wir planen die Arbeiten passend zu Vegetation, Nutzung und Standort. Regelmäßige Pflege hält Außenbereiche übersichtlich und sorgt dafür, dass Zugänge und Wege gut nutzbar bleiben.'),
('Vom Rasen bis zum Beet','Unser Angebot umfasst Rasenpflege, Hecken- und Strauchpflege, Beetpflege, Bewässerung und Laubentfernung. Auch die Pflege befestigter Wege lässt sich einbeziehen. Schnittarbeiten stimmen wir mit den örtlichen Gegebenheiten und den jeweils geltenden Schutzbestimmungen ab.'),
('Für ein stimmiges Gesamtbild','Gerade bei Wohnanlagen und Gewerbeflächen wirken gepflegte Außenbereiche und saubere Eingänge zusammen. Wir verbinden die Grünflächenpflege auf Wunsch mit Hausmeisterleistungen und Reinigung. Der Pflegeumfang wird objektbezogen festgelegt und lässt sich im Jahresverlauf anpassen.')],['Rasen- & Beetpflege','Hecken- & Strauchpflege','Laubentfernung','Bewässerung & Wegepflege']),
('immobilienservice','Immobilienservice','Ihr Objekt. Gemeinsam betreut.','service-7.webp','Reinigung, Betreuung und Sicherheit sinnvoll verbinden – mit einem zentralen Ansprechpartner.',[
('Leistungen sinnvoll zusammenführen','Wenn mehrere Dienstleister an einer Immobilie arbeiten, entstehen viele Schnittstellen. COMPAKT bündelt auf Wunsch die Betreuung: von der Reinigung über Hausmeisterleistungen und Grünpflege bis zum Winterdienst und Wachschutz. Sie entscheiden, welche Bausteine Ihr Objekt benötigt.'),
('Absprachen, die im Alltag tragen','Wir erfassen Anforderungen, Flächen und vorhandene Abläufe. Daraus entsteht ein abgestimmter Leistungsumfang mit klaren Zuständigkeiten. Die Koordination anstehender Reparaturen und Wartungen sowie Mieter- oder Empfangsservices können nach Bedarf dazugehören.'),
('Kompetenzen der FORM Gruppe','Für zusätzliche Fachaufgaben greifen wir auf die Zusammenarbeit innerhalb der FORM Gruppe zurück. Das ermöglicht eine abgestimmte Organisation auch dann, wenn mehrere Gewerke gebraucht werden. Welche Leistungen vor Ort verfügbar sind, klären wir anhand Ihres Standorts und des konkreten Auftrags.')],['Gebündelte Objektbetreuung','Reinigung & Außenpflege','Koordination von Reparaturen','Empfangs- & Mieterservice']),
('entlastungsbetrag','Alltagshilfe','Mehr Unterstützung. Mehr Alltag.','alltag.webp','Praktische Unterstützung im Haushalt und bei alltäglichen Aufgaben – persönlich abgestimmt.',[
('Unterstützung dort, wo sie gebraucht wird','Einkaufen, Ordnung halten und alltägliche Wege können mit der Zeit anstrengender werden. Wir besprechen gemeinsam, welche Hilfe entlastet und welche Aufgaben übernommen werden sollen. Eine feste Abstimmung gibt Ihnen und Ihren Angehörigen Orientierung.'),
('Leistungen individuell vereinbaren','Zum angefragten Unterstützungsangebot können Einkaufshilfe, Haushaltshilfe, Reinigung, Gartenpflege und Fahrdienste gehören. Art, Umfang und Verfügbarkeit klären wir persönlich. Nicht jede Leistung ist automatisch über die Pflegekasse abrechenbar.'),
('Entlastungsbetrag richtig einordnen','Pflegebedürftige in häuslicher Pflege können bis zu 131 Euro monatlich für anerkannte Unterstützungsleistungen nutzen, auch mit Pflegegrad 1. Voraussetzung und Erstattungsfähigkeit hängen vom anerkannten Angebot und den geltenden Regelungen ab. Bitte klären Sie die Kostenübernahme vorab mit Ihrer Pflegekasse. Unsere Beratung erreichen Sie unter 033702 60 70.')],['Einkaufshilfe','Haushaltsunterstützung','Reinigungsservice','Individuelle Alltagsbegleitung']),
('drohnenservice','Drohnenservice','Neue Perspektiven fürs Gebäude.','service-1.webp','Reinigung und visuelle Inspektion schwer zugänglicher Flächen im Verbund mit dem FORM Drohnenservice.',[
('Erst prüfen, dann abheben','Nicht jedes Gebäude und jede Fläche eignet sich für einen Drohneneinsatz. Wir klären Zugänglichkeit, Umfeld, Material und Ziel der Arbeiten. Auch Wetter, erforderliche Freigaben und die Absicherung des Einsatzbereichs werden bei der Planung berücksichtigt.'),
('Reinigung und Inspektion','Drohnen können bei geeigneten Objekten die Reinigung oder die visuelle Bestandsaufnahme unterstützen. Fotos können dabei helfen, auffällige Bereiche zu dokumentieren und weitere Maßnahmen gezielt zu planen. Welche Technik sinnvoll ist, entscheidet sich anhand der konkreten Aufgabe.'),
('Ein Ansprechpartner im Verbund','COMPAKT koordiniert Ihre Anfrage mit dem FORM Drohnenservice. Sie beschreiben uns Objekt, Standort und gewünschte Leistung; vorhandene Fotos und Informationen zur Fläche erleichtern die erste Einschätzung. Anschließend stimmen wir Vorgehen, Umfang und Termin ab.')],['Objektbezogene Beratung','Reinigung geeigneter Flächen','Visuelle Inspektion','Dokumentation nach Vereinbarung'])
]
REGIONS = [
('brandenburg','Brandenburg','Regional verwurzelt. Nah an Ihrem Objekt.','Von Fürstenwalde/Spree aus betreuen wir Immobilien im regionalen Umfeld. Ob Wohnanlage in Bad Saarow, Büro in Frankfurt (Oder) oder Gewerbefläche in Erkner: Wir stimmen die Leistungen auf Ihr Objekt und die Wege vor Ort ab.','Fürstenwalde/Spree · Bad Saarow · Frankfurt (Oder) · Erkner · Grünheide · Königs Wusterhausen','Wohnanlagen, einzelne Gewerbeobjekte und größere Außenflächen stellen unterschiedliche Anforderungen. In Brandenburg spielen häufig Zufahrten, Grünanlagen und saisonale Pflege eine wichtige Rolle. Wir betrachten Innen- und Außenbereiche zusammen, damit Reinigung, Hausmeisterdienst und Winterdienst aufeinander abgestimmt sind.','Bei Objekten im Umland sind ein genauer Lageplan und Angaben zu Zugängen hilfreich. Gemeinsam legen wir fest, welche Bereiche regelmäßig betreut werden und welche Aufgaben nach Bedarf anfallen. Für weiter entfernte Standorte prüfen wir die Einsatzmöglichkeiten im Verbund der FORM Gruppe.'),
('berlin','Berlin','Service für den Rhythmus der Stadt.','In Berlin treffen Büroflächen, Wohnhäuser und gewerbliche Nutzungen oft auf engem Raum zusammen. COMPAKT stimmt Reinigung, Objektbetreuung und Sicherheitsleistungen auf diese Abläufe ab – im Netzwerk der FORM Gruppe.','Bürogebäude · Wohnanlagen · Gewerbehöfe · Gemeinschaftsflächen','Bei stark genutzten Gebäuden müssen Reinigungszeiten, Lieferverkehr und Besucherströme zusammenpassen. Deshalb klären wir Zugang, Schlüsselübergabe und Betriebszeiten vor dem Start. Treppenhäuser und Eingangsbereiche werden im Leistungsverzeichnis genauso berücksichtigt wie Sanitärräume oder Glasflächen.','Für größere Portfolios ist eine einheitliche Leistungsbeschreibung hilfreich. Sie erleichtert den Vergleich zwischen Standorten und macht Sonderaufgaben erkennbar. Teilen Sie uns Bezirk, Objektart und Umfang mit; die konkrete Betreuung und Verfügbarkeit stimmen wir anschließend persönlich ab.'),
('sachsen','Sachsen','Objektservice über Landesgrenzen hinweg.','Sie suchen einen Ansprechpartner für Reinigung, Sicherheit und Immobilienservice in Sachsen? COMPAKT bündelt Ihre Anfrage und prüft mit den Unternehmen der FORM Gruppe die passende Betreuung für Ihren Standort.','Anfragen für Leipzig · Dresden · Chemnitz und das jeweilige Umland','Gewerbliche Liegenschaften und Wohnungsbestände benötigen eine Betreuung, die zur Nutzung passt. Bei mehreren Standorten sind klare Qualitätsanforderungen besonders wichtig: Welche Flächen gehören zum Auftrag, welche Intervalle sind vorgesehen und wie werden Mängel gemeldet? Diese Punkte klären wir gemeinsam vor der Angebotserstellung.','Die Planung für Sachsen erfolgt objektbezogen. Eine pauschale Zusage für jede Leistung an jedem Ort wäre wenig hilfreich. Wir prüfen Leistungsumfang, Entfernung, Personal- und Partnerverfügbarkeit und besprechen mit Ihnen einen realistischen Start. So erhalten Sie eine nachvollziehbare Grundlage für Ihre Entscheidung.'),
('sachsen-anhalt','Sachsen-Anhalt','Ein klarer Plan für Ihre Liegenschaft.','Für Immobilien in Sachsen-Anhalt koordinieren wir Anfragen zu Reinigung, Wachschutz, Hausmeisterleistungen und Außenpflege innerhalb unseres Unternehmensverbunds. Ausgangspunkt ist immer der Bedarf Ihres Objekts.','Anfragen für Magdeburg · Halle (Saale) · Dessau-Roßlau und Umgebung','An Gewerbestandorten müssen Innenreinigung, Zufahrten und Außenanlagen oft parallel organisiert werden. Bei Wohnanlagen kommen die Anliegen von Verwaltung und Mietern hinzu. Ein abgestimmter Leistungskatalog hilft, diese Aufgaben zu verbinden und Zuständigkeiten transparent zu halten.','Nennen Sie uns Standort, Flächengröße und gewünschte Leistungen. Fotos oder ein vorhandenes Leistungsverzeichnis beschleunigen die Einschätzung. Wir prüfen die regionalen Einsatzmöglichkeiten und informieren Sie, welche Betreuung für Ihr Objekt umsetzbar ist. Auch die Einbindung bestehender Dienstleister kann abgestimmt werden.')
]
